add("cuda-template", "#include <iostream>\n#include <cuda_runtime.h>\n\n// 检查 CUDA 错误的宏\n#define CHECK_CUDA_ERROR(val) check((val), #val, __FILE__, __LINE__)\ntemplate <typename T>\nvoid check(T err, const char* const func, const char* const file,\n           const int line) {\n    if (err != cudaSuccess) {\n        std::cerr << \"CUDA Runtime Error at: \" << file << \":\" << line\n                  << std::endl;\n        std::cerr << cudaGetErrorString(err) << \" \" << func << std::endl;\n        std::exit(EXIT_FAILURE);\n    }\n}\n\n// CUDA 核函数\n__global__ void ${1:kernelName}(${2:parameters}) {\n\t// 获取线程索引\n\tint idx = blockIdx.x * blockDim.x + threadIdx.x;\n\t\n\t// 核函数逻辑\n\t$0\n}\n\nint main() {\n\t// 初始化数据\n\tint N = ${3:1024};\n\tsize_t size = N * sizeof(${4:int});\n\t\n\t// 主机内存分配\n\t${4:int} *h_${5:data} = new ${4:int}[N];\n\t\n\t// 设备内存分配\n\t${4:int} *d_${5:data};\n\tCHECK_CUDA_ERROR(cudaMalloc(&d_${5:data}, size));\n\t\n\t// 数据传输：主机 -> 设备\n\tCHECK_CUDA_ERROR(cudaMemcpy(d_${5:data}, h_${5:data}, size, cudaMemcpyHostToDevice));\n\t\n\t// 配置核函数启动参数\n\tint blockSize = ${6:256};\n\tint gridSize = (N + blockSize - 1) / blockSize;\n\t\n\t// 启动核函数\n\t${1:kernelName}<<<gridSize, blockSize>>>(d_${5:data});\n\tCHECK_CUDA_ERROR(cudaGetLastError());\n\t\n\t// 等待 GPU 完成\n\tCHECK_CUDA_ERROR(cudaDeviceSynchronize());\n\t\n\t// 数据传输：设备 -> 主机\n\tCHECK_CUDA_ERROR(cudaMemcpy(h_${5:data}, d_${5:data}, size, cudaMemcpyDeviceToHost));\n\t\n\t// 清理资源\n\tCHECK_CUDA_ERROR(cudaFree(d_${5:data}));\n\tdelete[] h_${5:data};\n\t\n\treturn 0;\n}", "Complete CUDA program template with error checking")
