add("reduction-sum", "__global__ void reductionSum(const ${1:float} *input, ${1:float} *output, int N) {\n\t__shared__ ${1:float} sdata[${2:256}];\n\t\n\tint tid = threadIdx.x;\n\tint i = blockIdx.x * blockDim.x * 2 + threadIdx.x;\n\tint gridSize = blockDim.x * 2 * gridDim.x;\n\t\n\t// 第一步：读取并相加两个元素\n\tsdata[tid] = 0;\n\twhile (i < N) {\n\t\tsdata[tid] += input[i];\n\t\tif (i + blockDim.x < N) {\n\t\t\tsdata[tid] += input[i + blockDim.x];\n\t\t}\n\t\ti += gridSize;\n\t}\n\t__syncthreads();\n\t\n\t// 第二步：块内归约\n\tfor (int s = blockDim.x / 2; s > 0; s >>= 1) {\n\t\tif (tid < s) {\n\t\t\tsdata[tid] += sdata[tid + s];\n\t\t}\n\t\t__syncthreads();\n\t}\n\t\n\t// 第三步：写入块结果\n\tif (tid == 0) {\n\t\toutput[blockIdx.x] = sdata[0];\n\t}\n}", "Parallel reduction sum kernel")
